package edu.pe.cibertec.saibm.membresia.application.usecase;
import java.time.*; import java.util.*; import edu.pe.cibertec.saibm.membresia.application.port.in.*; import edu.pe.cibertec.saibm.membresia.application.port.out.*; import edu.pe.cibertec.saibm.membresia.domain.event.*; import edu.pe.cibertec.saibm.membresia.domain.model.*;
public class MembershipService implements MembershipUseCase {private final MembershipStorePort store;public MembershipService(MembershipStorePort s){store=s;}public List<PlanView> activePlans(Instant at){return store.activePlans(at).stream().map(this::view).toList();}public PlanView plan(UUID id){return store.plan(id).map(this::view).orElseThrow(()->new IllegalArgumentException("Plan not found"));}public PlanView createPlan(PlanCommand c){var p=new Plan(UUID.randomUUID(),c.code(),c.name(),c.reservationLimit(),1,c.validFrom(),c.validUntil(),true,null);store.save(p);event(MembershipEventType.PLAN_UPDATED,Map.of("planId",p.id(),"version",p.version()),"","");return view(p);}public PlanView updatePlan(UUID id,PlanCommand c){var p=store.plan(id).orElseThrow(()->new IllegalArgumentException("Plan not found"));var next=p.revise(c.name(),c.reservationLimit(),c.validFrom(),c.validUntil());store.save(p.closeAt(c.validFrom()));store.save(next);event(MembershipEventType.PLAN_UPDATED,Map.of("planId",next.id(),"version",next.version()),"","");return view(next);}public void deactivatePlan(UUID id){var p=store.plan(id).orElseThrow(()->new IllegalArgumentException("Plan not found"));store.save(p.deactivate());event(MembershipEventType.PLAN_UPDATED,Map.of("planId",id,"version",p.version()),"","");}public AssignmentView assign(AssignmentCommand c,String key,String correlation){if(key==null||key.isBlank())throw new IllegalArgumentException("Idempotency-Key is required");var hash=key+":"+c.userId()+":"+c.planId()+":"+c.validFrom()+":"+c.validUntil();var old=store.assignmentByKey(key);if(old.isPresent())return replay(old.get(),hash);var p=store.plan(c.planId()).filter(x->x.validAt(c.validFrom())).orElseThrow(()->new IllegalArgumentException("Plan unavailable"));var previous=store.activeAssignment(c.userId(),c.validFrom());previous.ifPresent(x->{store.save(x.expire());store.history(new MembershipHistory(UUID.randomUUID(),x.userId(),x.id(),"CHANGED",Instant.now(),correlation));});var a=MembershipAssignment.create(UUID.randomUUID(),c.userId(),p.id(),p.code(),p.version(),p.reservationLimit(),c.validFrom(),c.validUntil(),key,hash,null);if(store.insert(a)==0)return replay(store.assignmentByKey(key).orElseThrow(),hash);store.history(new MembershipHistory(UUID.randomUUID(),a.userId(),a.id(),previous.isPresent()?"CHANGED":"ASSIGNED",Instant.now(),correlation));event(previous.isPresent()?MembershipEventType.CHANGED:MembershipEventType.ASSIGNED,Map.of("assignmentId",a.id(),"userId",a.userId(),"planVersion",a.planVersion()),correlation,"");return view(a);}public int expireDue(Instant at,String correlation){int count=0;for(var a:store.expiring(at)){store.save(a.expire());store.history(new MembershipHistory(UUID.randomUUID(),a.userId(),a.id(),"EXPIRED",Instant.now(),correlation));event(MembershipEventType.EXPIRED,Map.of("assignmentId",a.id(),"userId",a.userId()),correlation,"");count++;}return count;}public EntitlementView entitlement(String user,Instant at){var a=store.activeAssignment(user,at);return a.map(x->new EntitlementView(user,true,x.reservationLimit(),x.planCode(),x.planVersion(),x.validUntil())).orElseGet(()->new EntitlementView(user,false,0,"",0,null));}public List<MembershipHistory> history(String user){return store.history(user);}private AssignmentView replay(MembershipAssignment a,String hash){if(!hash.equals(a.requestHash()))throw new IllegalStateException("Idempotency conflict");return view(a);}private void event(MembershipEventType type,Map<String,Object> payload,String c,String cause){store.outbox(new MembershipEvent(UUID.randomUUID(),type.wireName(),1,Instant.now(),c,cause,"membresia-service",payload));}private PlanView view(Plan p){return new PlanView(p.id(),p.code(),p.name(),p.reservationLimit(),p.version(),p.validFrom(),p.validUntil(),p.active());}private AssignmentView view(MembershipAssignment a){return new AssignmentView(a.id(),a.userId(),a.planId(),a.planCode(),a.planVersion(),a.reservationLimit(),a.validFrom(),a.validUntil(),a.active());}}
